detectionRule.ruleCode:
rule Memory_AMSI_Bypass_Patch {
  meta:
    description = "Detects classic 6-byte E_INVALIDARG patch in amsi.dll memory"
    mitre = "T1562.001"
  strings:
    $patch_x64 = { B8 57 00 07 80 C3 }
  condition:
    $patch_x64
}

