detectionRule.ruleCode:
rule Reflective_DLL_Loader_Stub {
  meta:
    description = "Detects ReflectiveLoader export and PEB walking shellcode"
    mitre = "T1620"
  strings:
    $exp = "ReflectiveLoader" ascii
    $mz_loop = { 66 81 39 4D 5A 75 }
  condition:
    any of them
}
